	private void openRepository(boolean legacy) throws Exception {
		this.legacy = legacy;
		if (legacy) {
			LmdbCompatibilityFixtures.extract("v2-empty-inline-false.zip", dataDir.toPath());
		}
		openRepository();
	}

	private void openRepository() {
		store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setInlineLiterals(!legacy));
		repository = new SailRepository(store);
		repository.init();
	}

	private void reopenReady() throws Exception {
		repository.shutDown();
		openRepository();
		assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
				.as(store.getDirectAdjacencyReadinessDescription())
				.isTrue();
	}

	private static IRI iri(String local) {
		return VF.createIRI(EX + local);
	}

	private static BindingSet pair(Value s, Value o) {
		return new ListBindingSet(List.of("s", "o"), s, o);
	}

	private record Mode(String name, boolean nativeEngine, boolean nodeIds) {
		void configure() {
			System.setProperty(NATIVE, Boolean.toString(nativeEngine));
			System.setProperty(NODE_IDS, Boolean.toString(nodeIds));
		}
	}
